/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		certificationFields
	} = api.data.cert.taskData;
	const {
		value
	} = event.payload;

	var checkedObj = {};

	certificationFields.split(',').forEach((field) => {
		checkedObj[field] = value;
	});

	return {
		propName: 'attributeCheckedState',
		value: checkedObj
	};
}

 /**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	const certificationFields = api?.data?.cert?.taskData?.certificationFields;
  const {
    attributeCheckedState
  } = api.state;

  if (!certificationFields)
    return false;

  const attributeKeys = Object.keys(attributeCheckedState);
  if (attributeKeys.length < certificationFields.split(',').length)
    return false;
  return !attributeKeys.some(key => !attributeCheckedState[key]);
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		attributeCheckedState
	} = api.state;
	const {
		name,
		value
	} = event.payload;

	let updatedChecked = {
		...attributeCheckedState
	};

	updatedChecked[name] = value;

	return {
		propName: 'attributeCheckedState',
		value: updatedChecked
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const {
    name
  } = api.item.value;
  const {
    attributeCheckedState
  } = api.state;
	return attributeCheckedState.hasOwnProperty(name) && attributeCheckedState[name];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return [{"id":"values","label": helpers.translateSync('{0} values', api.item.value.inputValues.length)}];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const {
    allRowsSelected,
    selectedRowIds
  } = api.data.list.selectionProps;
  const {
    taskData: {
      isTaskClosed
    }
  } = api.data.cert;
  const {
    attributeCheckedState
  } = api.state;
	return isTaskClosed || !((allRowsSelected || selectedRowIds.length) && Object.keys(attributeCheckedState).some(key => attributeCheckedState[key]));
}

